/**
 * The error of every SDK call. Programs read `api_error_code(error)`; the
 * text is for people and never holds secrets.
 */
public enum ApiError: Swift.Error, Equatable, Hashable, Foundation.LocalizedError {

    
    
    case Closed
    case Cancelled
    case DeadlineExceeded
    case InvalidInput(field: String, reason: String
    )
    case InvalidId(kind: String, reason: String
    )
    case CapacityExceeded(resource: String, limit: UInt64, detail: String
    )
    case LimitReached(resource: String, limit: UInt64, detail: String
    )
    case Storage(code: ErrorCode, detail: String
    )
    case Transport(code: ErrorCode, peer: EndpointId?, detail: String
    )
    case Authorization(code: ErrorCode, detail: String
    )
    case State(code: ErrorCode, detail: String
    )
    case Internal(detail: String
    )

    

    

    
    public var errorDescription: String? {
        String(reflecting: self)
    }
    
}

#if compiler(>=6)
extension ApiError: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeApiError: FfiConverterRustBuffer {
    typealias SwiftType = ApiError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> ApiError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .Closed
        case 2: return .Cancelled
        case 3: return .DeadlineExceeded
        case 4: return .InvalidInput(
            field: try FfiConverterString.read(from: &buf), 
            reason: try FfiConverterString.read(from: &buf)
            )
        case 5: return .InvalidId(
            kind: try FfiConverterString.read(from: &buf), 
            reason: try FfiConverterString.read(from: &buf)
            )
        case 6: return .CapacityExceeded(
            resource: try FfiConverterString.read(from: &buf), 
            limit: try FfiConverterUInt64.read(from: &buf), 
            detail: try FfiConverterString.read(from: &buf)
            )
        case 7: return .LimitReached(
            resource: try FfiConverterString.read(from: &buf), 
            limit: try FfiConverterUInt64.read(from: &buf), 
            detail: try FfiConverterString.read(from: &buf)
            )
        case 8: return .Storage(
            code: try FfiConverterTypeErrorCode.read(from: &buf), 
            detail: try FfiConverterString.read(from: &buf)
            )
        case 9: return .Transport(
            code: try FfiConverterTypeErrorCode.read(from: &buf), 
            peer: try FfiConverterOptionTypeEndpointId.read(from: &buf), 
            detail: try FfiConverterString.read(from: &buf)
            )
        case 10: return .Authorization(
            code: try FfiConverterTypeErrorCode.read(from: &buf), 
            detail: try FfiConverterString.read(from: &buf)
            )
        case 11: return .State(
            code: try FfiConverterTypeErrorCode.read(from: &buf), 
            detail: try FfiConverterString.read(from: &buf)
            )
        case 12: return .Internal(
            detail: try FfiConverterString.read(from: &buf)
            )

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: ApiError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case .Closed:
            writeInt(&buf, Int32(1))
        
        
        case .Cancelled:
            writeInt(&buf, Int32(2))
        
        
        case .DeadlineExceeded:
            writeInt(&buf, Int32(3))
        
        
        case let .InvalidInput(field,reason):
            writeInt(&buf, Int32(4))
            FfiConverterString.write(field, into: &buf)
            FfiConverterString.write(reason, into: &buf)
            
        
        case let .InvalidId(kind,reason):
            writeInt(&buf, Int32(5))
            FfiConverterString.write(kind, into: &buf)
            FfiConverterString.write(reason, into: &buf)
            
        
        case let .CapacityExceeded(resource,limit,detail):
            writeInt(&buf, Int32(6))
            FfiConverterString.write(resource, into: &buf)
            FfiConverterUInt64.write(limit, into: &buf)
            FfiConverterString.write(detail, into: &buf)
            
        
        case let .LimitReached(resource,limit,detail):
            writeInt(&buf, Int32(7))
            FfiConverterString.write(resource, into: &buf)
            FfiConverterUInt64.write(limit, into: &buf)
            FfiConverterString.write(detail, into: &buf)
            
        
        case let .Storage(code,detail):
            writeInt(&buf, Int32(8))
            FfiConverterTypeErrorCode.write(code, into: &buf)
            FfiConverterString.write(detail, into: &buf)
            
        
        case let .Transport(code,peer,detail):
            writeInt(&buf, Int32(9))
            FfiConverterTypeErrorCode.write(code, into: &buf)
            FfiConverterOptionTypeEndpointId.write(peer, into: &buf)
            FfiConverterString.write(detail, into: &buf)
            
        
        case let .Authorization(code,detail):
            writeInt(&buf, Int32(10))
            FfiConverterTypeErrorCode.write(code, into: &buf)
            FfiConverterString.write(detail, into: &buf)
            
        
        case let .State(code,detail):
            writeInt(&buf, Int32(11))
            FfiConverterTypeErrorCode.write(code, into: &buf)
            FfiConverterString.write(detail, into: &buf)
            
        
        case let .Internal(detail):
            writeInt(&buf, Int32(12))
            FfiConverterString.write(detail, into: &buf)
            
        }
    }
}


